#' Summarize connectivity received by each evaluated receptor
summarize_connectivity_by_receptor <- function(exchange) {
  if (!nrow(exchange)) return(data.frame()); candidate <- exchange[exchange$within_evaluation_distance, ]; groups <- split(candidate, candidate$receptor_id)
  sm <- function(x) if (all(is.na(x))) NA_real_ else mean(x, na.rm = TRUE); sn <- function(x, f) if (all(is.na(x))) NA_real_ else f(x, na.rm = TRUE); ss <- function(x) if (all(is.na(x))) NA_real_ else sum(x, na.rm = TRUE)
  do.call(rbind, lapply(groups, function(x) data.frame(receptor_id = x$receptor_id[1], n_source_runs_evaluated = length(unique(x$run_id)), n_unique_sources_evaluated = length(unique(x$source_id)), n_unique_sources_intercepting = length(unique(x$source_id[x$intercept])), total_intercept_events = sum(x$intercept), intercept_fraction = sum(x$intercept) / nrow(x), mean_first_arrival_hours = sm(x$first_arrival_hour[x$intercept]), minimum_first_arrival_hours = sn(x$first_arrival_hour[x$intercept], min), mean_exposure_duration_hours = sm(x$exposure_duration_hours[x$intercept]), maximum_particle_count = sn(x$particle_count_max, max), total_particle_count_cumulative = ss(x$particle_count_cumulative), total_decayed_mass_cumulative = ss(x$decayed_mass_cumulative), total_decayed_concentration_hourly_sum = ss(x$decayed_concentration_hourly_sum), first_intercept_datetime_utc = if (any(x$intercept)) min(x$first_arrival_datetime_utc[x$intercept], na.rm = TRUE) else as.POSIXct(NA, tz = "UTC"), last_intercept_datetime_utc = if (any(x$intercept)) max(x$first_arrival_datetime_utc[x$intercept], na.rm = TRUE) else as.POSIXct(NA, tz = "UTC"), stringsAsFactors = FALSE)))
}
